mapper.sql:
WHERE cr.counselor_id = #{query.counselorId}

    AND cr.report_status = #{query.status}


    AND (su.real_name LIKE CONCAT('%', #{query.studentKeyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{query.studentKeyword}, '%'))

WHERE cr.report_status = 'SUBMITTED'

    AND (su.real_name LIKE CONCAT('%', #{query.studentKeyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{query.studentKeyword}, '%'))


    AND cr.counselor_id = #{query.counselorId}


    AND cr.problem_type_id = #{query.problemTypeId}


    AND cr.close_type = #{query.closeType}


    AND DATE(cr.submit_time) >= #{query.startDate}


    AND DATE(cr.submit_time) <= #{query.endDate}

